#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=9

# Run from the repo root no matter where the wizard was started; CDK reads infra/.env.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE="infra/.env"
STACK="SlackBots-ItTickets"
PY310="${LOCALAPPDATA:-}/Programs/Python/Python310/python.exe"

banner "slack-bots · one-time setup (AWS + GitHub + Slack)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "AWS CLI v2"
say "The pip-installed AWS CLI v1 shadows the v2 installer on your PATH."
note "Currently: $(aws --version 2>&1 | head -n1)"
if aws --version 2>&1 | grep -q '^aws-cli/1'; then
  if confirm "Uninstall the pip AWS CLI v1 (Python 3.10) so v2 takes over?"; then
    if [[ -x "$PY310" ]]; then "$PY310" -m pip uninstall -y awscli
    else python -m pip uninstall -y awscli; fi
    hash -r
  fi
fi
if confirm "Update AWS CLI v2 to the latest version with winget? (Windows asks for admin rights)"; then
  winget upgrade --id Amazon.AWSCLI -e || winget install --id Amazon.AWSCLI -e \
    || warn "winget changed nothing; v2 may already be current"
  hash -r
fi
# A fresh install lands here even when this shell's PATH predates it.
if [[ -d "/c/Program Files/Amazon/AWSCLIV2" ]]; then
  export PATH="/c/Program Files/Amazon/AWSCLIV2:$PATH"
fi
note "Now: $(aws --version 2>&1 | head -n1)"
if ! aws --version 2>&1 | grep -q '^aws-cli/2'; then
  warn "aws still isn't v2: open a new terminal (or fix PATH) and re-run the wizard."
  exit 1
fi
note "Other terminals pick up the change once reopened."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "AWS account & region"
say "The wizard uses your local (admin) AWS credentials for the one-time steps."
until IDENTITY=$(aws sts get-caller-identity --query '[Account,Arn]' --output text 2>/dev/null); do
  warn "No working AWS credentials found."
  step "In another terminal run:  aws configure   (access key of an admin IAM user)"
  pause "Press Enter to retry"
done
DETECTED_ACCOUNT=$(cut -f1 <<<"$IDENTITY")
note "Signed in as $(cut -f2 <<<"$IDENTITY")"
if confirm "Deploy to AWS account $DETECTED_ACCOUNT?"; then
  write_env AWS_ACCOUNT_ID "$DETECTED_ACCOUNT"
else
  warn "Switch credentials (e.g. export AWS_PROFILE=...) and re-run the wizard."
  exit 1
fi
if [[ -z "$(_existing AWS_REGION || true)" ]]; then write_env AWS_REGION "ca-central-1"; fi
ask AWS_REGION "AWS region:"
write_env AWS_REGION "$AWS_REGION"
OIDC_ARN=$(aws iam list-open-id-connect-providers --output text \
  --query "OpenIDConnectProviderList[?contains(Arn, 'token.actions.githubusercontent.com')].Arn" 2>/dev/null || true)
if [[ -n "$OIDC_ARN" && "$OIDC_ARN" != "None" ]]; then
  note "This account already has a GitHub OIDC provider; reusing it."
  write_env GITHUB_OIDC_PROVIDER_ARN "$OIDC_ARN"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Agent & budget alert"
say "The Agent is the Slack user who receives every ticket (you, for this PoC)."
step "In Slack: click your avatar → Profile → ⋮ (More) → Copy member ID."
until ask AGENT_SLACK_USER_ID "Paste the member ID (starts with U or W):" \
  && [[ "$AGENT_SLACK_USER_ID" =~ ^[UW][A-Z0-9]{6,}$ ]]; do
  warn "That doesn't look like a Slack member ID."
done
write_env AGENT_SLACK_USER_ID "$AGENT_SLACK_USER_ID"
say "AWS emails this address if the monthly bill goes over \$1."
until ask BUDGET_ALERT_EMAIL "Budget alert email:" && [[ "$BUDGET_ALERT_EMAIL" == *@*.* ]]; do
  warn "Please enter an email address."
done
write_env BUDGET_ALERT_EMAIL "$BUDGET_ALERT_EMAIL"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "CDK bootstrap + GitHub deploy role"
say "Creates CDK's bootstrap resources in $AWS_REGION, then the role GitHub Actions"
say "deploys with (only from main of this repo). This is the only stack you ever"
say "deploy by hand. CDK shows the IAM changes and asks you to approve them."
if confirm "Run cdk bootstrap and deploy SlackBots-GithubOidc now?"; then
  ( cd infra \
    && npx cdk bootstrap "aws://$AWS_ACCOUNT_ID/$AWS_REGION" \
    && npx cdk deploy SlackBots-GithubOidc )
else
  SKIPPED+=("cd infra && npx cdk bootstrap && npx cdk deploy SlackBots-GithubOidc")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub repository variables"
say "CI reads these to synthesize and deploy. None of them is secret."
set_var AWS_ACCOUNT_ID "$AWS_ACCOUNT_ID"
set_var AWS_REGION "$AWS_REGION"
set_var AGENT_SLACK_USER_ID "$AGENT_SLACK_USER_ID"
set_var BUDGET_ALERT_EMAIL "$BUDGET_ALERT_EMAIL"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Deploy the bot from GitHub"
say "Runs the CI workflow on main, which deploys SlackBots-Shared and $STACK."
if confirm "Start the deploy now?"; then
  STARTED=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  gh workflow run CI --ref main
  note "Waiting for the run to appear…"
  RUN_ID=""
  for _ in $(seq 1 30); do
    RUN_ID=$(gh run list --workflow CI --event workflow_dispatch --limit 1 \
      --json databaseId,createdAt --jq ".[] | select(.createdAt >= \"$STARTED\") | .databaseId")
    [[ -n "$RUN_ID" ]] && break
    sleep 2
  done
  if [[ -n "$RUN_ID" ]] && gh run watch "$RUN_ID" --exit-status; then
    note "Deploy finished."
  else
    warn "The deploy didn't succeed. See: gh run view ${RUN_ID:-<run id>} --log-failed"
    pause "Fix it and re-run CI; press Enter once it's green"
  fi
fi
SLACK_REQUEST_URL=$(aws cloudformation describe-stacks --stack-name "$STACK" --region "$AWS_REGION" \
  --query "Stacks[0].Outputs[?OutputKey=='SlackRequestUrl'].OutputValue" --output text 2>/dev/null || true)
if [[ -z "$SLACK_REQUEST_URL" || "$SLACK_REQUEST_URL" == "None" ]]; then
  warn "Couldn't read the bot URL from $STACK. Deploy it, then re-run the wizard."
  exit 1
fi
write_env SLACK_REQUEST_URL "$SLACK_REQUEST_URL"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Create the Slack app"
MANIFEST=$(mktemp --suffix=.yaml)
sed "s#REPLACE_WITH_FUNCTION_URL#$SLACK_REQUEST_URL#g" apps/it-tickets/manifest.yaml > "$MANIFEST"
if command -v clip.exe >/dev/null 2>&1; then
  clip.exe < "$MANIFEST"
  note "The manifest, with your bot URL filled in, is on your clipboard."
else
  note "Manifest with your bot URL filled in: $MANIFEST"
fi
open_url "https://api.slack.com/apps?new_app=1"
step "Choose 'From a manifest', pick your workspace → Next."
step "Select the YAML tab, replace its content with the clipboard → Next → Create."
step "(App created on an earlier run? Open it → App Manifest → paste → Save instead.)"
step "Left menu → Install App → Install to <workspace> → Allow."
pause "Press Enter once the app is installed"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Slack secrets → AWS SSM"
say "Stored as free SecureString parameters, never in .env or git."
step "In your app: OAuth & Permissions → copy the Bot User OAuth Token (xoxb-…)."
until ask_secret SLACK_BOT_TOKEN "Paste the bot token:" && [[ "$SLACK_BOT_TOKEN" == xoxb-* ]]; do
  warn "Bot tokens start with xoxb-."
done
step "Basic Information → App Credentials → Signing Secret → Show → copy."
until ask_secret SLACK_SIGNING_SECRET "Paste the signing secret:" && [[ -n "$SLACK_SIGNING_SECRET" ]]; do
  warn "The signing secret can't be empty."
done
put_param() {
  # MSYS_NO_PATHCONV stops Git Bash rewriting the leading "/" of the name into a Windows path.
  MSYS_NO_PATHCONV=1 aws ssm put-parameter --region "$AWS_REGION" --name "$1" \
    --type SecureString --overwrite --value "$2" >/dev/null
  printf '  %s✓ stored%s %s\n' "$GREEN" "$RESET" "$1"
}
put_param /slack-bots/it-tickets/bot-token "$SLACK_BOT_TOKEN"
put_param /slack-bots/it-tickets/signing-secret "$SLACK_SIGNING_SECRET"
unset SLACK_BOT_TOKEN SLACK_SIGNING_SECRET
note "Replacing a secret later? Re-run CI afterwards so running Lambdas reload it."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Try it"
open_url "slack://open"
step "In any channel type:  /ticket Test ticket  → fill in the modal → Open ticket."
step "The IT Tickets app DMs you a Confirmation and, as the Agent, a Ticket card."
step "On the card click Take, then Resolve with a note; watch the Confirmation thread."
LOG_GROUP=$(aws cloudformation describe-stack-resources --stack-name "$STACK" --region "$AWS_REGION" \
  --query "StackResources[?ResourceType=='AWS::Logs::LogGroup'].PhysicalResourceId" --output text 2>/dev/null || true)
note "Something off? Tail the bot's logs with:"
note "  MSYS_NO_PATHCONV=1 aws logs tail $LOG_GROUP --region $AWS_REGION --follow"
pause "Press Enter when you're done"

finish
}

run_wizard "$@"; exit
